/*
[演算法邏輯說明]
計算兩個字串的最長共同子序列 (Longest Common Subsequence, LCS) 的長度。
1. 使用動態規劃 (Dynamic Programming)。
2. 令 dp[i][j] 為字串 s1 前 i 個字元與字串 s2 前 j 個字元的最長共同子序列長度。
3. 轉移方程：
   - 如果 s1[i-1] == s2[j-1]，則 dp[i][j] = dp[i-1][j-1] + 1。
   - 如果 s1[i-1] != s2[j-1]，則 dp[i][j] = max(dp[i-1][j], dp[i][j-1])。
4. 使用二維陣列來儲存中間結果，由於空間限制，也可以使用滾動陣列將空間複雜度優化為 O(min(N, M))，但在此問題 1000x1000 的範圍下，標準二維陣列即可。
*/

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    string s1, s2;
    while (getline(cin, s1)) {
        if (!getline(cin, s2)) break;
        int n1 = s1.length();
        int n2 = s2.length();
        vector<vector<int>> dp(n1 + 1, vector<int>(n2 + 1, 0));
        for (int i = 1; i <= n1; ++i) {
            for (int j = 1; j <= n2; ++j) {
                if (s1[i - 1] == s2[j - 1]) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }
        cout << dp[n1][n2] << endl;
    }
    return 0;
}
